StandardsGuides:RegisterClassData({key="warrior",token="WARRIOR",name="Warrior",items={["warrior-763"]={s="Bandages",sp={"ARMS","FURY","PROT"},w="Heals between pulls faster than food. Warriors have little self-healing, so bandages save a lot of downtime.",sk="Skill 240; recipe source not listed",m="2 x Mageweave Cloth",tt={"Requires First Aid (175)","Use: Heals 1104 damage over 8 sec."},k="c",a="First Aid · Skill 240; recipe source unknown",q=1,p="First Aid",id=8545,n="Heavy Mageweave Bandage"},["warrior-602"]={s="Devices",sp={"ARMS","FURY","PROT"},w="Utility device. Compare the effect and cooldown with what you already carry.",sk="Trainer (skill 85)",m="1 x Copper Modulator  , 2 x Handful of Copper Bolts  , 1 x Bronze Bar  , 1 x Wool Cloth",tt={"Requires Engineering (85)","Use: Drops a target dummy on the ground that attracts nearby monsters to attack it. Lasts for 15 seconds or until killed. (2 Min Cooldown)"},k="c",a="Engineering · Trainer (skill 85)",q=1,p="Engineering",id=4366,n="Target Dummy"},["warrior-653"]={s="Explosives",sp={"ARMS","FURY","PROT"},w="Area damage or a stun that works in any stance and costs no Rage. Useful when a pull goes wrong.",sk="Schematic: EZ-Thro Copper Bomb XL (skill 130)",m="3 x Copper Bar  , 4 x Coarse Blasting Powder  , 1 x Silver Contact  , 1 x EZ-Thro Wrap",tt={"Use: Inflicts 43 to 57 Fire damage and stuns targets in a 5 yd radius for 1 sec. Any damage will break the effect. (1 Min Cooldown)"},k="c",a="Engineering · Schematic: EZ-Thro Copper Bomb XL (skill 130)",q=1,p="Engineering",id=260795,n="EZ-Thro Copper Bomb XL"},["warrior-744"]={s="Potions",sp={"ARMS","FURY","PROT"},tt={"Requires Level 45","Use: Increases Attack Power by 56 for 30 sec."},w="Emergency healing or utility. Compare the effect and cooldown with what you already carry.",sk="Skill 240; recipe source not listed",m="3 x Blindweed  , 2 x Firebloom  , 1 x Crystal Vial",a="Alchemy · Skill 240; recipe source unknown",k="c",id=250942,q=1,p="Alchemy",rl=45,n="Superior Frenzy Potion"},["warrior-806"]={s="Food & Drink",sp={"ARMS","FURY","PROT"},w="Well Fed buff food: restores health and gives a melee or survival stat, plus extra kill experience while leveling.",sk="Recipe: Brilliant Smallfish (skill 1)",m="1 x Raw Brilliant Smallfish",tt={"Use: Restores 59 health over 18 sec. Must remain seated while eating. If you spend at least 10 sec eating, you will become well fed and gain 2 Attack Power for 15 min. Additionally, experience gained from kills is increased by 5%."},k="c",a="Cooking · Recipe: Brilliant Smallfish (skill 1)",q=1,p="Cooking",id=6290,n="Brilliant Smallfish"},["warrior-774"]={s="Remedies",sp={"ARMS","FURY","PROT"},w="Removes poison, disease or bleed effects, which you cannot cleanse on your own.",sk="Manual: Potent Anti-Venom (skill 230)",m="1 x Swollen Venom Sac",tt={"Use: Target is cured of poisons up to level 45. (1 Min Cooldown)"},k="c",a="First Aid · Manual: Potent Anti-Venom (skill 230)",q=1,p="First Aid",id=255715,n="Potent Anti-Venom"},["warrior-721"]={s="Flasks",sp={"ARMS","FURY","PROT"},tt={"Requires Level 50","Use: You turn to stone, protecting you from all physical attacks and spells for 1 min, but during that time you cannot attack, move or cast spells. You can only have the effect of one flask at a time. (3 Sec Cooldown)"},w="Stat buff for dungeons and hard pulls. Check that it does not overwrite a stronger buff of the same type.",sk="Recipe: Flask of Petrification (skill 300)",m="30 x Stonescale Oil  , 10 x Mountain Silversage  , 1 x Black Lotus  , 1 x Crystal Vial",a="Alchemy · Recipe: Flask of Petrification (skill 300)",k="c",id=13506,q=1,p="Alchemy",rl=50,n="Flask of Petrification"},["warrior-621"]={s="Explosives",sp={"ARMS","FURY","PROT"},tt={"Requires Level 10","Use: The dynamite for Non-Engineers that nearly always gets to the target! Inflicts 51 to 69 Fire damage in a 5 yard radius. (1 Min Cooldown)","\"So E-Z, even your cat could throw it.\""},w="Area damage or a stun that works in any stance and